"""Post a message to a Slack channel via ``chat.postMessage``.

Usage:
    pysae-ai-tools slack post-message \\
        --channel C0123ABCDEF \\
        --text "Hello, world"

    # Thread reply
    pysae-ai-tools slack post-message \\
        --channel C0123ABCDEF \\
        --thread-ts 1700000000.000100 \\
        --text "follow-up"

    # Multiline text via stdin (--text -)
    pysae-ai-tools slack post-message --channel C... --text - <<EOF
    line 1
    line 2
    EOF

    # Append a discreet "generated by Claude" context block under the message
    pysae-ai-tools slack post-message --channel C... --text "..." --ai-footer

Uses :func:`pysae_ai_tools.slack.common.get_slack_token` for authentication:
the user token locally, the bot token in CI.

Output (JSON, one line):
    {"ok": true, "ts": "1700000000.000200", "channel": "C0123ABCDEF"}
    {"ok": false, "error": "<slack error code or message>"}
"""

import json
import sys
from typing import Annotated

import typer

from .client import SlackApiError, slack_post
from .common import (
    REVIEW_METADATA_EVENT_TYPE,
    get_slack_token,
    log_not_posted,
    resolve_channel,
)

# Default attribution shown in the context block when --ai-footer is set. The
# tool name links to its public PyPI page (mrkdwn <url|label> renders as a
# clickable link inside a context block).
AI_FOOTER_TEXT = ":robot_face: Rédigé par Claude via <https://pypi.org/project/pysae-ai-tools|pysae-ai-tools>"

# chat.postMessage rejects a section block whose text exceeds this length.
SECTION_TEXT_LIMIT = 3000


def build_blocks(body: str, footer_text: str) -> list[dict[str, object]]:
    """Wrap the message body in a section block followed by a context attribution.

    A ``context`` block renders the attribution as small, greyed-out text — the
    same discreet footer the Slack MCP appends — visually detached from the body.
    """
    return [
        {"type": "section", "text": {"type": "mrkdwn", "text": body}},
        {"type": "divider"},
        {"type": "context", "elements": [{"type": "mrkdwn", "text": footer_text}]},
    ]


def post_message(token: str, payload: dict[str, object]) -> dict[str, object]:
    """Call chat.postMessage (JSON body) and return the parsed response."""
    return slack_post(token, "chat.postMessage", payload)


def post_message_joining(token: str, payload: dict[str, object], *, join: bool) -> dict[str, object]:
    """Post the message; with ``join``, self-join the channel on ``not_in_channel`` and retry once.

    The bot needs the ``channels:join`` scope (public channels only). This makes
    one-way broadcasts to a public channel — e.g. the #mep deploy channel —
    self-healing if the bot is ever removed, without a manual re-invite.
    """
    try:
        return post_message(token, payload)
    except SlackApiError as e:
        if not (join and e.code == "not_in_channel"):
            raise
        try:
            slack_post(token, "conversations.join", {"channel": payload["channel"]})
        except SlackApiError:
            pass
        return post_message(token, payload)


cli = typer.Typer()


@cli.command()
def main(
    channel: Annotated[
        str,
        typer.Option("--channel", help="Slack channel ID, or a known name (e.g. 'mep')."),
    ],
    text: Annotated[
        str,
        typer.Option(
            "--text",
            help="Message text (mrkdwn). Use '-' to read from stdin.",
        ),
    ],
    thread_ts: Annotated[
        str,
        typer.Option("--thread-ts", help="Parent message ts — post as a thread reply."),
    ] = "",
    broadcast: Annotated[
        bool,
        typer.Option(
            "--broadcast",
            help="With --thread-ts, also post the reply to the parent channel (reply_broadcast).",
        ),
    ] = False,
    ai_footer: Annotated[
        bool,
        typer.Option(
            "--ai-footer",
            help="Append a discreet 'generated by Claude' context block under the message.",
        ),
    ] = False,
    ai_footer_text: Annotated[
        str,
        typer.Option("--ai-footer-text", help="Override the attribution text used by --ai-footer."),
    ] = AI_FOOTER_TEXT,
    join: Annotated[
        bool,
        typer.Option(
            "--join",
            help="Self-join the (public) channel on 'not_in_channel' and retry — needs the channels:join scope.",
        ),
    ] = False,
    review_project: Annotated[
        str,
        typer.Option(
            "--review-project",
            help="GitLab project URL — with --review-mr-iid, stamps structured review metadata so "
            "ask-review / mark-merged can find this exact message (not a human's quoting the same link).",
        ),
    ] = "",
    review_mr_iid: Annotated[
        int,
        typer.Option("--review-mr-iid", help="GitLab MR IID — paired with --review-project to stamp review metadata."),
    ] = 0,
    metadata_event_type: Annotated[
        str,
        typer.Option(
            "--metadata-event-type",
            help="Stamp arbitrary Slack message metadata under this event_type (with --metadata-payload). "
            "Lets find-thread / other finders locate this message by identity rather than by text.",
        ),
    ] = "",
    metadata_payload: Annotated[
        str,
        typer.Option(
            "--metadata-payload", help="JSON object used as the metadata event_payload (with --metadata-event-type)."
        ),
    ] = "",
) -> None:
    """Post a message to a Slack channel (or thread) via chat.postMessage."""
    body = sys.stdin.read() if text == "-" else text
    if not body.strip():
        log_not_posted("empty message body")
        print(json.dumps({"ok": False, "error": "empty message body"}))
        raise typer.Exit(code=1)

    token = get_slack_token()
    if not token:
        log_not_posted("no Slack token available — run /env-resolve or set SLACK_USER_TOKEN / SLACK_BOT_TOKEN")
        print(json.dumps({"ok": False, "error": "no Slack token available"}))
        raise typer.Exit(code=1)

    resolved_channel = resolve_channel(channel)
    if not resolved_channel.strip():
        log_not_posted(
            "target channel is empty — is the tech channel configured? "
            "(check `pysae-ai-tools project show slack.tech_channel_id`)"
        )
        print(json.dumps({"ok": False, "error": "empty channel"}))
        raise typer.Exit(code=1)

    # text always carries the full body: it is the notification fallback and the
    # substring the dedup search (slack ask-review) scans for the MR URL.
    payload: dict[str, object] = {"channel": resolved_channel, "text": body}
    # A section block caps at 3000 chars; above that, keep the plain-text post
    # rather than letting Slack reject the whole message.
    if ai_footer and len(body) <= SECTION_TEXT_LIMIT:
        payload["blocks"] = build_blocks(body, ai_footer_text)
    if thread_ts:
        payload["thread_ts"] = thread_ts
        if broadcast:
            payload["reply_broadcast"] = "true"
    # Stamp structured metadata so the message is found by its identity, not by
    # scanning text (which also matches unrelated posts). Generic event_type +
    # payload, or the --review-* shortcut for the common review-request case.
    if metadata_event_type:
        try:
            event_payload = json.loads(metadata_payload) if metadata_payload else {}
        except json.JSONDecodeError as e:
            print(json.dumps({"ok": False, "error": f"invalid --metadata-payload JSON: {e}"}))
            raise typer.Exit(code=1) from None
        if not isinstance(event_payload, dict):
            print(json.dumps({"ok": False, "error": "--metadata-payload must be a JSON object"}))
            raise typer.Exit(code=1)
        payload["metadata"] = {"event_type": metadata_event_type, "event_payload": event_payload}
    elif review_project and review_mr_iid:
        payload["metadata"] = {
            "event_type": REVIEW_METADATA_EVENT_TYPE,
            "event_payload": {"project": review_project.rstrip("/"), "mr_iid": review_mr_iid},
        }

    try:
        result = post_message_joining(token, payload, join=join)
    except SlackApiError as e:
        log_not_posted(f"Slack rejected the message: {e}")
        print(json.dumps({"ok": False, "error": str(e)}))
        raise typer.Exit(code=1) from None

    print(json.dumps({"ok": True, "ts": result.get("ts"), "channel": result.get("channel")}))


if __name__ == "__main__":
    cli()
